    "/api/health": {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        /**
         * 健康检查（公开，R15-A3）
         * @description 容器编排用的轻量活性探针：无鉴权。R32-C 起返回进程 uptime、启动时 间、服务版本（package.json version）、世界计数（环境数 + 仿真状态分 布）、全局 LLM 队列深度与 SQLite 探活结果。status=degraded 当数据库 不可用时。R74 起携带 decision.mode：'llm' = 生产姿态（LLM 决策且后 端存活）；'llm-unreachable' = 已配置但后端不可达（决策正退化为规则 线束，姿态受损）；'rule-test' = 规则线束（仅测试，非生产行为）。
         */
        get: {
            parameters: {
                query?: never;
                header?: never;
                path?: never;
                cookie?: never;
            };
            requestBody?: never;
            responses: {
                /** @description 健康状态（degraded 也是 200，探针按 status 字段判断） */
                200: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        "application/json": {
                            /** @enum {string} */
                            status: "ok" | "degraded";
                            version: string;
                            uptimeSec: number;
                            startedAt: string;
                            /** @description 注册门姿态（alpha 容量管控，schema v57）：inviteOnly=true 时 注册必须携带邀请码（RegisterRequest.inviteCode）。 */
                            auth: {
                                inviteOnly: boolean;
                            };
                            /** @description 决策姿态（R74）：llm=生产；llm-unreachable=后端不可达；rule-test=规则线束，仅测试。 */
                            decision: {
                                /** @enum {string} */
                                mode: "llm" | "llm-unreachable" | "rule-test";
                                /** @description 已配置的 LLM 模型名 */
                                model?: string;
                                /** @description 按职能模型路由摘要（仅配置时透出）：decision=发起决策+triage （LLM_DECISION_MODEL）、eval=应答评估（LLM_EVAL_MODEL）、 nl=NL 意图+提案审查（LLM_NL_MODEL）。值为规范形式 "model"（主后端 LLM_BASE_URL）或 "model@baseURL"（指向另一个 vLLM 实例）。未设置的路由回落 LLM_MODEL。 */
                                routes?: {
                                    decision?: string;
                                    eval?: string;
                                    nl?: string;
                                };
                            };
                            worlds: {
                                environments: number;
                                sims: {
                                    total: number;
                                    running: number;
                                    byState: {
                                        [key: string]: number;
                                    };
                                };
                            };
                            llmQueue: {
                                active: number;
                                queued: number;
                                maxConcurrent: number;
                                waitCount?: number;
                                avgWaitMs?: number;
                                maxWaitMs?: number;
                                depthHighWater?: number;
                            };
                            /** @description 小模型 fast-lane 队列（R44-dense-F4 起暴露）——dense 档全部 决策载荷走该道，仅看 llmQueue 会把峰值争用误读成空闲； 字段口径与 llmQueue 一致。plan-r84 Wave D 起并发槽位在 LLM_FAST_LANE_MIN/MAX（默认 8/32）间自适应，maxConcurrent 为当前档位；显式设 LLM_FAST_LANE_CONCURRENT 钉死时无 adaptive 字段 */
                            llmFastLaneQueue: {
                                active: number;
                                queued: number;
                                maxConcurrent: number;
                                waitCount?: number;
                                avgWaitMs?: number;
                                maxWaitMs?: number;
                                depthHighWater?: number;
                                /** @description 自适应档位边界（钉死模式不带此字段） */
                                adaptive?: {
                                    min: number;
                                    max: number;
                                };
                            };
                            checks: {
                                /** @enum {string} */
                                database: "ok" | "fail";
                            };
                        };
                    };
                };
            };
        };
        put?: never;
        post?: never;
        delete?: never;
        options?: never;
        head?: never;
        patch?: never;
        trace?: never;
    };
