            terminatedAt?: string;
            /** @description R99：仅 status='terminated' 时出现——终止结果（共享 terminatedAgreementOutcome 口径：有计量则取最近计量 outcome； AC 无计量行 / explicit 从未 active = cancelled；曾 active 后 终止 = completed）。 */
            outcome?: string;
