            consumerAgentId: string | null;
            consumerAgentName: string | null;
            consumer: components["schemas"]["OwnerRef"];
            providerAgentId: string;
            providerAgentName: string | null;
            provider: components["schemas"]["OwnerRef"];
            terms: components["schemas"]["AgreementTerms"];
