            termsEnforced: boolean;
            status: components["schemas"]["AgreementStatus"];
            /** @description T57（R6/u2-F-2-5）：首次进入 active 的时刻（v59 列，恒在读取面 透出）。null = 从未生效（explicit 提案从未被接受）；terminated 合约的 outcome 判定（ended-without-delivery vs cancelled）即以 本时刻为据。 */
            activatedAt?: string | null;
            /** @description 行到达当前状态的原因（v60 起；仅在有记录时出现）——平台事件 （provider-unavailable / service-unavailable / ac-completed / ac-cancelled）或 R102 起 party 决策附带的自由文本原因 （reject/suspend/terminate 的 reason 参数）。未记录时不出现， 展示层显示"未记录原因"而非 null。 */
            statusReason?: string;
            /**
             * @description 建立途径（§3.1）：explicit = 市场提案经提供方 decide； ac = AC 握手成功自动落的 ephemeral agreement（出生即 active， 随协作结束 terminate，Phase 2；可用 AC_EPHEMERAL_AGREEMENTS=false 关闭）。
             * @enum {string}
             */
            source: "explicit" | "ac";
            /** @description source=ac 时所属 AC 协作 id；否则 null */
            collaborationId: string | null;
