            backingDeviceDrift?: {
                deviceId?: string;
                deviceName?: string;
                /** @description 缺失该设备的可指向 running 仿真 */
                absentFrom?: {
                    simulationId: string;
                    state: string;
                }[];
                /** @description 行动指引——重启漂移仿真重建，或 invoke 不带 simulationId 落在权威世界会话 */
                note?: string;
            };
