            provenance: {
                computationKind: string;
                /** @description 实际参与求值的输入规模。devices 恒等于被圈定并实际读到的 设备数（T-065：声明 inputs.devices 的计算只统计该集合—— 计算永远读不到、也永远不会多报声明之外的设备）。 */
                inputsSummary: {
                    zones: number;
                    devices: number;
                    eventsWindowed: number;
                };
                providerAgentId: string;
                registeredBy: string;
                /** Format: date-time */
                computedAtWall: string;
                simTimeSec: number;
                /** @description 计算出这一帧的 sim（计算时事实）。T57b（R6/u2-F-2-2）起缓存帧 保留该溯源（不再置 null）；「定向目标 sim」与「计算帧 sim」 的区别由顶层 simulationId（读取目标）+ cached 标志承载。 */
                simulationId: string | null;
                cached: boolean;
            };
            /** @description T57a（R6，u4-F2）：规格声明了 event 指标时存在——窗口长度，按 **仿真秒**计（多个 event 指标取最大窗）。 */
            eventWindowSec?: number;
            /** @description T57a：与 eventWindowSec 同时存在——求值时源 sim 的窗口口径推进 速率（窗口均值，缺省即时估计/标称速度）。二者相除 ≈ 该窗口的 真实秒跨度；CLI human 道在空窗 ⚠ 里渲染这一换算。 */
            effectiveSpeedPerSec?: number;
            /** @description 距 computedAtWall 的秒数 */
            freshnessSec: number;
            stale: boolean;
